script.setup:
const gl=ctx.gl;
if(!gl.getExtension('EXT_color_buffer_float')) throw new Error('부동소수점 렌더 타깃을 지원하는 WebGL2가 필요합니다.');
const vs=ctx.utils.FULLSCREEN_VERTEX_SHADER;
const sim=ctx.utils.createProgram(vs, `#version 300 es
precision highp float;
uniform sampler2D u_field;
uniform vec2 u_size;
uniform vec2 u_cursor;
uniform vec2 u_delta;
uniform float u_brush;
uniform float u_stir;
uniform float u_active;
uniform float u_feed;
uniform float u_kill;
uniform float u_step;
in vec2 v_uv;
out vec4 outColor;
vec2 sampleAt(vec2 q){
 vec2 pos=clamp(q,vec2(0.5),u_size-0.5)-0.5;
 vec2 f=fract(pos); ivec2 i=ivec2(floor(pos));
 ivec2 hi=ivec2(u_size)-1;
 return mix(mix(texelFetch(u_field,clamp(i,ivec2(0),hi),0).rg,texelFetch(u_field,clamp(i+ivec2(1,0),ivec2(0),hi),0).rg,f.x),mix(texelFetch(u_field,clamp(i+ivec2(0,1),ivec2(0),hi),0).rg,texelFetch(u_field,clamp(i+ivec2(1,1),ivec2(0),hi),0).rg,f.x),f.y);
}
void main(){
 vec2 p=gl_FragCoord.xy;
 vec2 rel=p-u_cursor;
 float brush=exp(-dot(rel,rel)/(u_brush*u_brush));
 float travel=length(u_delta);
 float spin=0.3*travel*u_stir*brush;
 vec2 q=p-u_delta*brush*u_stir-vec2(-rel.y,rel.x)*spin/max(u_brush,1.0);
 vec2 c=sampleAt(q);
 vec2 lap=-c;
 lap+=0.2*(sampleAt(q+vec2(1,0))+sampleAt(q-vec2(1,0))+sampleAt(q+vec2(0,1))+sampleAt(q-vec2(0,1)));
 lap+=0.05*(sampleAt(q+vec2(1,1))+sampleAt(q+vec2(-1,1))+sampleAt(q+vec2(1,-1))+sampleAt(q-vec2(1,1)));
 float react=c.x*c.y*c.y;
 vec2 rate=vec2(lap.x-react+u_feed*(1.0-c.x),0.5*lap.y+react-(u_feed+u_kill)*c.y);
 c=clamp(c+u_step*rate,0.0,1.0);
 float ink=u_active*brush*0.085;
 c=mix(c,vec2(0.35,0.43),ink);
 outColor=vec4(c,0,1);
}`);
const display=ctx.utils.createProgram(vs, `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform sampler2D u_field;
uniform vec2 u_size;
uniform vec2 u_resolution;
uniform vec4 u_mouse;
uniform float u_time;
uniform float u_brush;
uniform float u_contrast;
vec2 field(vec2 uv){
 vec2 p=clamp(uv*u_size-0.5,vec2(0),u_size-1.001); ivec2 i=ivec2(floor(p)); vec2 f=fract(p);
 return mix(mix(texelFetch(u_field,i,0).rg,texelFetch(u_field,i+ivec2(1,0),0).rg,f.x),mix(texelFetch(u_field,i+ivec2(0,1),0).rg,texelFetch(u_field,i+ivec2(1,1),0).rg,f.x),f.y);
}
void main(){
 vec2 c=field(v_uv);
 vec2 px=1.0/u_size;
 float gx=(field(v_uv+vec2(px.x,0)).y-field(v_uv-vec2(px.x,0)).y);
 float gy=(field(v_uv+vec2(0,px.y)).y-field(v_uv-vec2(0,px.y)).y);
 float v=clamp((c.y-0.022)*3.7*u_contrast,0.0,1.0);
 vec3 dark=vec3(0.012,0.037,0.064);
 vec3 teal=vec3(0.025,0.41,0.43);
 vec3 mint=vec3(0.51,0.91,0.77);
 vec3 cream=vec3(0.91,0.98,0.80);
 vec3 col=mix(dark,teal,smoothstep(0.015,0.44,v));
 col=mix(col,mint,smoothstep(0.33,0.77,v));
 col=mix(col,cream,smoothstep(0.76,1.0,v));
 vec3 normal=normalize(vec3(-gx*4.0,-gy*4.0,0.55));
 float light=dot(normal,normalize(vec3(-0.5,0.7,1.0)));
 col*=0.76+0.34*light;
 col+=vec3(0.22,0.42,0.36)*pow(max(dot(reflect(-normalize(vec3(-0.5,0.7,1.0)),normal),vec3(0,0,1)),0.0),24.0)*smoothstep(0.16,0.6,v)*0.18;
 vec2 scr=gl_FragCoord.xy;
 vec2 cursor=u_mouse.xy;
 float r=u_brush*u_resolution.x/u_size.x;
 float ring=1.0-smoothstep(0.5,1.5,abs(length(scr-cursor)-r));
 float pressed=step(0.0,u_mouse.z);
 col=mix(col,vec3(0.84,1.0,0.93),ring*pressed*0.55);
 float vignette=1.0-0.16*dot((v_uv-0.5)*1.25,(v_uv-0.5)*1.25);
 col*=vignette;
 outColor=vec4(pow(max(col,vec3(0)),vec3(0.94)),1);
}`);
ctx.state.sim=sim;ctx.state.display=display;
ctx.state.allocate=(w,h)=>{
 const size=640;
 const sw=Math.max(80,Math.round(size*w/Math.max(w,h)));const sh=Math.max(80,Math.round(size*h/Math.max(w,h)));
 if(ctx.state.target)ctx.state.target.resize(sw,sh);else ctx.state.target=ctx.utils.createPingPong(sw,sh,{internalFormat:gl.RGBA16F,format:gl.RGBA,type:gl.FLOAT,filter:gl.NEAREST});
 ctx.state.sw=sw;ctx.state.sh=sh;
 const data=new Float32Array(sw*sh*4);
 for(let y=0;y<sh;y++)for(let x=0;x<sw;x++){
  const wx=x+18*Math.sin(y*0.041)+13*Math.cos(x*0.026+y*0.019);
  const wy=y+16*Math.cos(x*0.034)+11*Math.sin(y*0.024-x*0.022);
  const wave=Math.sin(wx*0.22+0.9*Math.sin(wy*0.083))+0.48*Math.cos(wy*0.18+0.7*Math.sin(wx*0.06));
  const b=Math.max(0,Math.min(1,(0.32-Math.abs(wave))*4.0));
  const i=4*(y*sw+x);data[i]=1-0.65*b;data[i+1]=0.34*b;data[i+3]=1;
 }
 for(const dest of [ctx.state.target.read(),ctx.state.target.write()]){
  gl.bindTexture(gl.TEXTURE_2D,dest.texture);gl.texSubImage2D(gl.TEXTURE_2D,0,0,0,sw,sh,gl.RGBA,gl.FLOAT,data);
 }
 ctx.state.resetHeld=false;
};
ctx.state.allocate(...ctx.resolution);
gl.disable(gl.DEPTH_TEST);gl.disable(gl.BLEND);
for(let i=0;i<160;i++){
 const t=ctx.state.target;gl.bindFramebuffer(gl.FRAMEBUFFER,t.write().framebuffer);gl.viewport(0,0,ctx.state.sw,ctx.state.sh);
 gl.useProgram(sim);ctx.utils.bindTexture(sim,'u_field',t.read().texture,0);
 ctx.utils.drawFullscreen(sim,{u_size:[ctx.state.sw,ctx.state.sh],u_cursor:[-1000,-1000],u_delta:[0,0],u_brush:30,u_stir:1,u_active:0,u_feed:0.035,u_kill:0.060,u_step:1});t.swap();
}
gl.bindFramebuffer(gl.FRAMEBUFFER,null);gl.viewport(0,0,...ctx.resolution);

script.render:
// Steps above 1 make the simulation unstable and the pattern dies out on slow machines.
const gl=ctx.gl;const s=ctx.state;const [w,h]=ctx.resolution;
const sw=Math.max(80,Math.round(640*w/Math.max(w,h)));const sh=Math.max(80,Math.round(640*h/Math.max(w,h)));
if(sw!==s.sw||sh!==s.sh)s.allocate(w,h);
const reset=ctx.keys.has('KeyR');if(reset&&!s.resetHeld)s.allocate(w,h);s.resetHeld=reset;
const mouse=[ctx.mouse[0]*s.sw,(1-ctx.mouse[1])*s.sh];
let dx=(ctx.mouse[0]-ctx.mousePrev[0])*s.sw;let dy=-(ctx.mouse[1]-ctx.mousePrev[1])*s.sh;
const distance=Math.hypot(dx,dy);if(distance>50){dx*=50/distance;dy*=50/distance;}
const iterations=ctx.uniforms.u_pause?0:Math.max(1,Math.round(12*ctx.uniforms.u_speed));
const count=ctx.mouseDown?Math.max(1,iterations):iterations;
for(let i=0;i<count;i++){
 const t=s.target;gl.bindFramebuffer(gl.FRAMEBUFFER,t.write().framebuffer);gl.viewport(0,0,s.sw,s.sh);
 gl.useProgram(s.sim);ctx.utils.bindTexture(s.sim,'u_field',t.read().texture,0);
 ctx.utils.drawFullscreen(s.sim,{u_size:[s.sw,s.sh],u_cursor:mouse,u_delta:ctx.mouseDown&&i===0?[dx,dy]:[0,0],u_brush:ctx.uniforms.u_radius,u_stir:ctx.uniforms.u_force,u_active:ctx.mouseDown?1:0,u_feed:ctx.uniforms.u_feed,u_kill:ctx.uniforms.u_kill,u_step:ctx.uniforms.u_pause?0:Math.min(ctx.dt*60,1)});t.swap();
}
gl.bindFramebuffer(gl.FRAMEBUFFER,null);gl.viewport(0,0,w,h);gl.useProgram(s.display);ctx.utils.bindTexture(s.display,'u_field',s.target.read().texture,0);ctx.utils.drawFullscreen(s.display,{u_size:[s.sw,s.sh],u_brush:ctx.uniforms.u_radius});
